mapper.select:
SELECT message.*, child.status AS child_run_status FROM afv_agent_message message JOIN afv_agent_run run ON run.run_id = message.run_id LEFT JOIN afv_agent_run child ON message.role = 'tool' AND child.parent_run_id = message.run_id AND child.parent_tool_call_id = message.tool_call_id WHERE run.stream_run_id = #{streamRunId} AND message.deleted = 0 AND message.role != 'user'
AND run.run_id = #{sourceRunId}
ORDER BY message.message_order
